# GENERATED by `npx ray gen` from implementation/physics.ray - do not edit
# Rscript tests/r/test_G.R [filter] - every requirement on every fixture the package carries; a filter keeps the cases whose name contains it
options(expressions = 500000)
.here <- local({
  a <- commandArgs(FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f[1])) else getwd()
})
.lib <- file.path(.here, "..", "..", "languages", "physics.r", "R")
for (.f in c("rt.R", "physics.R", "theorems.R")) source(file.path(.lib, .f), encoding = "UTF-8", keep.source = FALSE)

.only <- commandArgs(TRUE)
.only <- if (length(.only)) .only[1] else NULL
.passed <- 0
.failed <- 0
.skipped <- 0
t_case <- function(name, body) {
  if (!is.null(.only) && !grepl(.only, name, fixed = TRUE)) return(invisible(NULL))
  t0 <- proc.time()[["elapsed"]]
  got <- tryCatch(text_of(body()), error = function(e) paste0("error: ", conditionMessage(e)))
  s <- proc.time()[["elapsed"]] - t0
  if (identical(got, "pass")) .passed <<- .passed + 1 else if (identical(got, "skip")) .skipped <<- .skipped + 1 else .failed <<- .failed + 1
  cat(sprintf("%s %s (%.2f s)%s\n", if (identical(got, "pass")) "ok  " else if (identical(got, "skip")) "skip" else "FAIL", name, s, if (got %in% c("pass", "skip")) "" else paste0(" - ", got)))
  invisible(NULL)
}

